<?php

namespace Digidirect\DigiDeals\Controller\Index;

class Clearance extends \Magento\Framework\App\Action\Action
{
    protected $_productCollection;
    
    protected $logger;
    
    protected $productRepository;
    
    public function __construct(
        \Magento\Framework\App\Action\Context $context,
        \Psr\Log\LoggerInterface $logger,
        \Magento\Catalog\Model\ResourceModel\Product\CollectionFactory $productCollection,
        \Magento\Catalog\Api\ProductRepositoryInterface $productRepository
    )
    {
        $this->logger = $logger;
        $this->_productCollection= $productCollection;
        $this->productRepository = $productRepository;
        parent::__construct($context);
    }

    public function execute()
    {
        $productCollection = $this->getProductCollections();
        foreach ($productCollection as $product) {
            try {
                $product->setCustomAttribute('clearance', true);
                $this->productRepository->save($product);
            } catch (Exception $ex) {
                $this->logger->info("add clearance, " . $ex->getMessage());
                continue;
            }
        }
        echo "Clearance Products Done!";
    }
    
